if mibBuilder.loadTexts: cxeCcProfileDnsLookupMax1.setDescription("This object enables/disables the Max1 Domain Name Server\n        (DNS) query operation when Max1 expires.\n        This object is used when a gateway-initiated message is not\n        acknowledged by the MGC. If the object is 'true', a DNS\n        query is performed to re-resolve MGC's domain name after\n        exhausting Max1 retries on any IP address associated with\n        the MGC.")
cxeCcProfileRetryMax2 = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 325, 1, 1, 2, 1, 11), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 20)).clone(7)).setMaxAccess("readcreate")
