cxeCcProfileCgTimeout = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 325, 1, 1, 2, 1, 24), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 3600)).clone(180)).setUnits('seconds').setMaxAccess("readcreate")
